INSERT INTO `beard_styles` VALUES (101,'BEARD_001','Sharp Boxed Beard','Professional','Oval,Round','Crisp geometric beard shape with defined cheek lines and square chin.','1. Trim overall length to 8mm.\n2. Edge cheek lines sharp at 45 degrees.\n3. Clean neck line 1 inch above adams apple.','https://images.unsplash.com/photo-1622286342621-4bd786c2447c?w=600&auto=format&fit=crop'),(102,'BEARD_002','Designer Heavy Stubble','Trendy','Oval,Square,Heart,Diamond','Rugged 3-day stubble look with soft blended edges.','1. Use 3mm guard over entire beard area.\n2. Taper neck fade smoothly.','https://images.unsplash.com/photo-1506794778202-cad84cf45f1d?w=600&auto=format&fit=crop'),(103,'BEARD_003','Short Corporate Beard','Professional','Oval,Round,Square,Rectangle','Neat, even short beard about 5 mm with clean cheek and neck lines for the office.','1. Trim the whole beard evenly with a 5 mm guard.\n2. Define a natural, low cheek line.\n3. Clean the neckline one finger above the Adam\'s apple.\n4. Tidy the moustache above the lip line.',''),(104,'BEARD_004','Classic Full Beard','Classic','Oval,Rectangle,Diamond,Heart','Well-groomed full beard about 2 cm, rounded at the chin with a connected moustache.','1. Trim the beard to about 2 cm, slightly longer at the chin.\n2. Round the chin shape.\n3. Shape the cheek line and neckline.\n4. Trim the moustache off the lip; finish with beard oil.',''),(105,'BEARD_005','Clean Shave','Classic','Oval,Round,Square,Heart,Diamond,Rectangle','Smooth, traditional clean shave for a fresh, polished look.','1. Trim existing beard short with clippers.\n2. Hot towel and pre-shave oil.\n3. Shave with the grain, then a careful second pass.\n4. Cold towel and alcohol-free aftershave balm.',''),(106,'BEARD_006','Van Dyke Goatee','Trendy','Round,Oval,Square','Stylish Van Dyke: chin beard and separate moustache with clean-shaven cheeks.','1. Shave the cheeks and sides of the jaw clean.\n2. Shape a chin beard about 1 cm, slightly pointed.\n3. Shape a separate moustache, leaving a small gap at the mouth corners.\n4. Define lines with a trimmer.',''),(107,'BEARD_007','Faded Short Beard','Trendy','Oval,Square,Round,Diamond','Modern short beard that fades from the sideburns into a fuller chin.','1. Fade the sideburns from 1 mm up to 6 mm.\n2. Keep the jaw and chin at 8 mm.\n3. Sharp cheek line, clean neckline.\n4. Blend with a trimmer for a smooth gradient.',''),(108,'BEARD_008','Circle Beard','Classic','Square,Oval,Rectangle','Traditional circle beard: moustache joined to a rounded chin beard, cheeks clean.','1. Shave the cheeks clean.\n2. Keep moustache and chin beard at about 6 mm.\n3. Connect them in a rounded circle around the mouth.\n4. Define the outline with a trimmer.',''),(109,'BEARD_009','Light Stubble','Professional','Oval,Round,Square,Heart,Diamond,Rectangle','Subtle, even 1-2 mm stubble with a tidy neckline for a smart, low-effort look.','1. Trim the whole beard area with a 1.5 mm guard.\n2. Clean the neckline and cheek edges.\n3. Keep the moustache the same length.',''),(110,'BEARD_010','Chevron Moustache + Stubble','Classic','Oval,Rectangle,Square','Bold, full chevron moustache over light stubble.','1. Trim the beard area to 2 mm stubble.\n2. Keep the moustache full, trimmed to the top of the lip.\n3. Shape the moustache into a slight downward chevron.\n4. Comb and finish with moustache wax.','');
/*!40000 ALTER TABLE `beard_styles` ENABLE KEYS */;
UNLOCK TABLES;

