INSERT INTO `haircut_instructions` VALUES (1,1,'{\"steps\": [\"1. Section center parting and cut curtain bangs sweeping past cheekbones at 45-degree angle.\", \"2. Create 90-degree interior long layers from collarbone down.\", \"3. Point-cut ends for soft seamless weight distribution.\", \"4. Blow-dry with large barrel round brush curling outward.\", \"5. Finish with light shine serum.\"]}','/api/v1/instructions/audio/1'),(2,2,'{\"steps\": [\"1. Section center parting and cut curtain bangs sweeping past cheekbones at 45-degree angle.\", \"2. Create 90-degree interior long layers from collarbone down.\", \"3. Point-cut ends for soft seamless weight distribution.\", \"4. Blow-dry with large barrel round brush curling outward.\", \"5. Finish with light shine serum.\"]}','/api/v1/instructions/audio/2'),(3,3,'{\"steps\": [\"1. Section center parting and cut curtain bangs sweeping past cheekbones at 45-degree angle.\", \"2. Create 90-degree interior long layers from collarbone down.\", \"3. Point-cut ends for soft seamless weight distribution.\", \"4. Blow-dry with large barrel round brush curling outward.\", \"5. Finish with light shine serum.\"]}','/api/v1/instructions/audio/3'),(4,4,'{\"steps\": [\"1. Section center parting and cut curtain bangs sweeping past cheekbones at 45-degree angle.\", \"2. Create 90-degree interior long layers from collarbone down.\", \"3. Point-cut ends for soft seamless weight distribution.\", \"4. Blow-dry with large barrel round brush curling outward.\", \"5. Finish with light shine serum.\"]}','/api/v1/instructions/audio/4'),(5,5,'{\"steps\": [\"1. Section center parting and cut curtain bangs sweeping past cheekbones at 45-degree angle.\", \"2. Create 90-degree interior long layers from collarbone down.\", \"3. Point-cut ends for soft seamless weight distribution.\", \"4. Blow-dry with large barrel round brush curling outward.\", \"5. Finish with light shine serum.\"]}','/api/v1/instructions/audio/5'),(6,6,'{\"steps\": [\"1. Section center parting and cut curtain bangs sweeping past cheekbones at 45-degree angle.\", \"2. Create 90-degree interior long layers from collarbone down.\", \"3. Point-cut ends for soft seamless weight distribution.\", \"4. Blow-dry with large barrel round brush curling outward.\", \"5. Finish with light shine serum.\"]}','/api/v1/instructions/audio/6'),(7,7,'{\"steps\": [\"1. Section center parting and cut curtain bangs sweeping past cheekbones at 45-degree angle.\", \"2. Create 90-degree interior long layers from collarbone down.\", \"3. Point-cut ends for soft seamless weight distribution.\", \"4. Blow-dry with large barrel round brush curling outward.\", \"5. Finish with light shine serum.\"]}','/api/v1/instructions/audio/7'),(8,8,'{\"steps\": [\"1. Section center parting and cut curtain bangs sweeping past cheekbones at 45-degree angle.\", \"2. Create 90-degree interior long layers from collarbone down.\", \"3. Point-cut ends for soft seamless weight distribution.\", \"4. Blow-dry with large barrel round brush curling outward.\", \"5. Finish with light shine serum.\"]}','/api/v1/instructions/audio/8'),(9,10,'{\"steps\": [\"1. Section center parting and cut curtain bangs sweeping past cheekbones at 45-degree angle.\", \"2. Create 90-degree interior long layers from collarbone down.\", \"3. Point-cut ends for soft seamless weight distribution.\", \"4. Blow-dry with large barrel round brush curling outward.\", \"5. Finish with light shine serum.\"]}','/api/v1/instructions/audio/10'),(10,12,'{\"steps\": [\"1. Section center parting and cut curtain bangs sweeping past cheekbones at 45-degree angle.\", \"2. Create 90-degree interior long layers from collarbone down.\", \"3. Point-cut ends for soft seamless weight distribution.\", \"4. Blow-dry with large barrel round brush curling outward.\", \"5. Finish with light shine serum.\"]}','/api/v1/instructions/audio/12'),(11,14,'{\"steps\": [\"1. Section center parting and cut curtain bangs sweeping past cheekbones at 45-degree angle.\", \"2. Create 90-degree interior long layers from collarbone down.\", \"3. Point-cut ends for soft seamless weight distribution.\", \"4. Blow-dry with large barrel round brush curling outward.\", \"5. Finish with light shine serum.\"]}','/api/v1/instructions/audio/14'),(12,16,'{\"steps\": [\"1. Section center parting and cut curtain bangs sweeping past cheekbones at 45-degree angle.\", \"2. Create 90-degree interior long layers from collarbone down.\", \"3. Point-cut ends for soft seamless weight distribution.\", \"4. Blow-dry with large barrel round brush curling outward.\", \"5. Finish with light shine serum.\"]}','/api/v1/instructions/audio/16'),(13,18,'{\"steps\": [\"1. Section center parting and cut curtain bangs sweeping past cheekbones at 45-degree angle.\", \"2. Create 90-degree interior long layers from collarbone down.\", \"3. Point-cut ends for soft seamless weight distribution.\", \"4. Blow-dry with large barrel round brush curling outward.\", \"5. Finish with light shine serum.\"]}','/api/v1/instructions/audio/18'),(14,20,'{\"steps\": [\"1. Section center parting and cut curtain bangs sweeping past cheekbones at 45-degree angle.\", \"2. Create 90-degree interior long layers from collarbone down.\", \"3. Point-cut ends for soft seamless weight distribution.\", \"4. Blow-dry with large barrel round brush curling outward.\", \"5. Finish with light shine serum.\"]}','/api/v1/instructions/audio/20'),(15,22,'{\"steps\": [\"1. Section center parting and cut curtain bangs sweeping past cheekbones at 45-degree angle.\", \"2. Create 90-degree interior long layers from collarbone down.\", \"3. Point-cut ends for soft seamless weight distribution.\", \"4. Blow-dry with large barrel round brush curling outward.\", \"5. Finish with light shine serum.\"]}','/api/v1/instructions/audio/22'),(16,23,'{\"steps\": [\"1. Curve drop fade around ear to nape.\", \"2. Point-cut forward fringe for messy texture.\"]}','/api/v1/instructions/audio/23'),(17,24,'{\"steps\": [\"1. Use #1 guard to start low taper at sideburns and nape.\", \"2. Blend into #2 guard moving upward.\", \"3. Point-cut 2 inches on top for textured volume.\", \"4. Apply matte clay for natural finish.\"]}','/api/v1/instructions/audio/24'),(18,25,'{\"steps\": [\"1. Establish perimeter baseline cut parallel to jawline.\", \"2. Elevate crown sections 90 degrees for soft top volume.\", \"3. Texturize weight behind ears with thinning shears.\", \"4. Smooth blow-dry with flat iron bevel at ends.\"]}','/api/v1/instructions/audio/25'),(19,26,'{\"steps\": [\"1. Establish U-shaped perimeter baseline at mid-back.\", \"2. Slide-cut front layers starting from chin down to ends.\", \"3. Blow-dry inward with large round brush.\"]}','/api/v1/instructions/audio/26'),(20,27,'{\"steps\": [\"1. Curve drop fade around ear to nape.\", \"2. Point-cut forward fringe for messy texture.\"]}','/api/v1/instructions/audio/27'),(21,28,'{\"steps\": [\"1. #2 guard on sides and back, tapering to #1 at the neckline.\", \"2. Scissor-cut top to 1-1.5 inches, slightly longer at the front.\", \"3. Blend the top into the sides with scissor-over-comb.\", \"4. Light matte paste brushed up at the front.\"]}','/api/v1/instructions/audio/28'),(22,29,'{\"steps\": [\"1. Use #1 guard to start low taper at sideburns and nape.\", \"2. Blend into #2 guard moving upward.\", \"3. Point-cut 2 inches on top for textured volume.\", \"4. Apply matte clay for natural finish.\"]}','/api/v1/instructions/audio/29'),(23,30,'{\"steps\": [\"1. #2 guard on sides tapering to #1 at the nape.\", \"2. Top cut to 1.5-2 inches, graduated longer to the front.\", \"3. Hard-define the side part with a comb.\", \"4. Style with a low-shine pomade.\"]}','/api/v1/instructions/audio/30'),(24,31,'{\"steps\": [\"1. Trim overall length to 8mm.\", \"2. Edge cheek lines sharp at 45 degrees.\", \"3. Clean neck line 1 inch above adams apple.\"]}','/api/v1/instructions/audio/31'),(25,32,'{\"steps\": [\"1. Patch test 48 hours before.\", \"2. Apply level 3-4 natural dark brown.\", \"3. Process 20-25 minutes.\", \"4. Rinse and condition.\"]}','/api/v1/instructions/audio/32'),(26,33,'{\"steps\": [\"1. Wrap the top section on medium perm rods.\", \"2. Process with a gentle waving lotion.\", \"3. Neutralise and rinse.\", \"4. Style with curl cream; sides unchanged.\"]}','/api/v1/instructions/audio/33'),(27,34,'{\"steps\": [\"1. Wrap the top section on medium perm rods.\", \"2. Process with a gentle waving lotion.\", \"3. Neutralise and rinse.\", \"4. Style with curl cream; sides unchanged.\"]}','/api/v1/instructions/audio/34'),(28,36,'{\"steps\": [\"1. Trim existing beard short with clippers.\", \"2. Hot towel and pre-shave oil.\", \"3. Shave with the grain, then a careful second pass.\", \"4. Cold towel and alcohol-free aftershave balm.\"]}','/api/v1/instructions/audio/36'),(29,37,'{\"steps\": [\"1. #2 guard on sides tapering to #1 at the nape.\", \"2. Top cut to 1.5-2 inches, graduated longer to the front.\", \"3. Hard-define the side part with a comb.\", \"4. Style with a low-shine pomade.\"]}','/api/v1/instructions/audio/37'),(30,38,'{\"steps\": [\"1. Establish U-shaped perimeter baseline at mid-back.\", \"2. Slide-cut front layers starting from chin down to ends.\", \"3. Blow-dry inward with large round brush.\", \"Wavy hair: leave slightly extra length so the wave sits naturally, and check the shape once dry.\"]}','/api/v1/instructions/audio/38'),(31,39,'{\"steps\": [\"1. Mid skin fade starting at temples.\", \"2. Blow dry top upward with round brush.\", \"3. Finish with high-hold texture powder.\", \"Follow the customer\'s oval face shape and head shape; check symmetry in the mirror before finishing.\"]}','/api/v1/instructions/audio/39'),(32,40,'{\"steps\": [\"1. Mid skin fade starting at temples.\", \"2. Blow dry top upward with round brush.\", \"3. Finish with high-hold texture powder.\"]}','/api/v1/instructions/audio/40'),(33,41,'{\"steps\": [\"1. Trim overall length to 8mm.\", \"2. Edge cheek lines sharp at 45 degrees.\", \"3. Clean neck line 1 inch above adams apple.\", \"Short beard today: shape the cheek line and neckline without taking off length.\"]}','/api/v1/instructions/audio/41'),(34,42,'{\"steps\": [\"1. Trim existing beard short with clippers.\", \"2. Hot towel and pre-shave oil.\", \"3. Shave with the grain, then a careful second pass.\", \"4. Cold towel and alcohol-free aftershave balm.\"]}','/api/v1/instructions/105/audio?selection_id=42'),(35,43,'{\"steps\": [\"1. Cut the perimeter just above the shoulders.\", \"2. Add long internal layers at 45 degrees.\", \"3. Soften the front with face-framing pieces.\", \"4. Blow-dry smooth with a slight bend at the ends.\", \"Thick hair: remove bulk at the crown and sides with texturising or thinning shears.\", \"Follow the customer\'s oval face shape and head shape; check symmetry in the mirror before finishing.\"]}','/api/v1/instructions/29/audio?selection_id=43'),(36,44,'{\"steps\": [\"1. Establish U-shaped perimeter baseline at mid-back.\", \"2. Slide-cut front layers starting from chin down to ends.\", \"3. Blow-dry inward with large round brush.\", \"Thick hair: remove bulk at the crown and sides with texturising or thinning shears.\", \"Follow the customer\'s oval face shape and head shape; check symmetry in the mirror before finishing.\"]}','/api/v1/instructions/10/audio?selection_id=44'),(37,45,'{\"steps\": [\"1. Cut shorter top layer framing cheekbones.\", \"2. Connect to longer bottom interior layer with point-cutting.\", \"3. Style with root volume spray.\", \"Follow the customer\'s oval face shape and head shape; check symmetry in the mirror before finishing.\"]}','/api/v1/instructions/11/audio?selection_id=45'),(38,46,'{\"steps\": [\"1. Cut medium layers from the collarbone.\", \"2. Add soft see-through face-framing pieces.\", \"3. Blow-dry ends under with a round brush or C-curl iron.\", \"4. Light hair oil for shine.\", \"Wavy hair: leave slightly extra length so the wave sits naturally, and check the shape once dry.\", \"Thick hair: remove bulk at the crown and sides with texturising or thinning shears.\", \"Follow the customer\'s oval face shape and head shape; check symmetry in the mirror before finishing.\"]}','/api/v1/instructions/32/audio?selection_id=46'),(39,47,'{\"steps\": [\"1. Cut medium layers from the collarbone.\", \"2. Add soft see-through face-framing pieces.\", \"3. Blow-dry ends under with a round brush or C-curl iron.\", \"4. Light hair oil for shine.\"]}','/api/v1/instructions/32/audio?selection_id=47'),(40,48,'{\"steps\": [\"1. Scissor-over-comb or #3 guard on back and sides.\", \"2. Square the neckline and tidy around the ears.\", \"3. Cut the top to 1.5-2 inches following head shape.\", \"4. Finish with a light cream, natural fall.\", \"Thick hair: remove bulk at the crown and sides with texturising or thinning shears.\", \"The customer wears a fringe now: confirm the new fringe length with them before cutting the front.\", \"Follow the customer\'s oval face shape and head shape; check symmetry in the mirror before finishing.\"]}','/api/v1/instructions/23/audio?selection_id=48'),(41,49,'{\"steps\": [\"1. Section center parting and cut curtain bangs sweeping past cheekbones at 45-degree angle.\", \"2. Create 90-degree interior long layers from collarbone down.\", \"3. Point-cut ends for soft seamless weight distribution.\", \"4. Blow-dry with large barrel round brush curling outward.\", \"5. Finish with light shine serum.\"]}','/api/v1/instructions/5/audio?selection_id=49'),(42,50,'{\"steps\": [\"1. Cut shorter top layer framing cheekbones.\", \"2. Connect to longer bottom interior layer with point-cutting.\", \"3. Style with root volume spray.\"]}','/api/v1/instructions/11/audio?selection_id=50'),(43,51,'{\"steps\": [\"1. Apply volumizing mousse to damp roots.\", \"2. Blow-dry section by section with 2-inch ceramic round brush.\", \"3. Set front sections in Velcro rollers for 10 minutes.\", \"Wavy hair: leave slightly extra length so the wave sits naturally, and check the shape once dry.\", \"Thick hair: remove bulk at the crown and sides with texturising or thinning shears.\", \"Follow the customer\'s oval face shape and head shape; check symmetry in the mirror before finishing.\"]}','/api/v1/instructions/14/audio?selection_id=51'),(44,52,'{\"steps\": [\"1. Apply volumizing mousse to damp roots.\", \"2. Blow-dry section by section with 2-inch ceramic round brush.\", \"3. Set front sections in Velcro rollers for 10 minutes.\", \"Wavy hair: leave slightly extra length so the wave sits naturally, and check the shape once dry.\", \"Thick hair: remove bulk at the crown and sides with texturising or thinning shears.\", \"Follow the customer\'s oval face shape and head shape; check symmetry in the mirror before finishing.\"]}','/api/v1/instructions/14/audio?selection_id=52'),(45,53,'{\"steps\": [\"1. Apply volumizing mousse to damp roots.\", \"2. Blow-dry section by section with 2-inch ceramic round brush.\", \"3. Set front sections in Velcro rollers for 10 minutes.\"]}','/api/v1/instructions/14/audio?selection_id=53'),(46,54,'{\"steps\": [\"1. Apply volumizing mousse to damp roots.\", \"2. Blow-dry section by section with 2-inch ceramic round brush.\", \"3. Set front sections in Velcro rollers for 10 minutes.\", \"Wavy hair: leave slightly extra length so the wave sits naturally, and check the shape once dry.\", \"Thick hair: remove bulk at the crown and sides with texturising or thinning shears.\"]}','/api/v1/instructions/14/audio?selection_id=54'),(47,55,'{\"steps\": [\"1. Apply volumizing mousse to damp roots.\", \"2. Blow-dry section by section with 2-inch ceramic round brush.\", \"3. Set front sections in Velcro rollers for 10 minutes.\"]}','/api/v1/instructions/14/audio?selection_id=55'),(48,56,'{\"steps\": [\"1. Establish U-shaped perimeter baseline at mid-back.\", \"2. Slide-cut front layers starting from chin down to ends.\", \"3. Blow-dry inward with large round brush.\", \"Wavy hair: leave slightly extra length so the wave sits naturally, and check the shape once dry.\", \"Thick hair: remove bulk at the crown and sides with texturising or thinning shears.\"]}','/api/v1/instructions/10/audio?selection_id=56'),(49,57,'{\"steps\": [\"1. Apply volumizing mousse to damp roots.\", \"2. Blow-dry section by section with 2-inch ceramic round brush.\", \"3. Set front sections in Velcro rollers for 10 minutes.\"]}','/api/v1/instructions/14/audio?selection_id=57'),(50,58,'{\"steps\": [\"1. Apply volumizing mousse to damp roots.\", \"2. Blow-dry section by section with 2-inch ceramic round brush.\", \"3. Set front sections in Velcro rollers for 10 minutes.\", \"Thick hair: remove bulk at the crown and sides with texturising or thinning shears.\", \"Follow the customer\'s oval face shape and head shape; check symmetry in the mirror before finishing.\"]}','/api/v1/instructions/14/audio?selection_id=58'),(51,59,'{\"steps\": [\"1. Apply volumizing mousse to damp roots.\", \"2. Blow-dry section by section with 2-inch ceramic round brush.\", \"3. Set front sections in Velcro rollers for 10 minutes.\", \"Wavy hair: leave slightly extra length so the wave sits naturally, and check the shape once dry.\", \"Thick hair: remove bulk at the crown and sides with texturising or thinning shears.\"]}','/api/v1/instructions/14/audio?selection_id=59'),(52,60,'{\"steps\": [\"1. Establish U-shaped perimeter baseline at mid-back.\", \"2. Slide-cut front layers starting from chin down to ends.\", \"3. Blow-dry inward with large round brush.\", \"Wavy hair: leave slightly extra length so the wave sits naturally, and check the shape once dry.\", \"Thick hair: remove bulk at the crown and sides with texturising or thinning shears.\"]}','/api/v1/instructions/10/audio?selection_id=60'),(53,61,'{\"steps\": [\"1. Apply volumizing mousse to damp roots.\", \"2. Blow-dry section by section with 2-inch ceramic round brush.\", \"3. Set front sections in Velcro rollers for 10 minutes.\", \"Wavy hair: leave slightly extra length so the wave sits naturally, and check the shape once dry.\", \"Thick hair: remove bulk at the crown and sides with texturising or thinning shears.\"]}','/api/v1/instructions/14/audio?selection_id=61'),(54,62,'{\"steps\": [\"1. Apply volumizing mousse to damp roots.\", \"2. Blow-dry section by section with 2-inch ceramic round brush.\", \"3. Set front sections in Velcro rollers for 10 minutes.\", \"Wavy hair: leave slightly extra length so the wave sits naturally, and check the shape once dry.\", \"Thick hair: remove bulk at the crown and sides with texturising or thinning shears.\"]}','/api/v1/instructions/14/audio?selection_id=62'),(55,63,'{\"steps\": [\"1. Apply volumizing mousse to damp roots.\", \"2. Blow-dry section by section with 2-inch ceramic round brush.\", \"3. Set front sections in Velcro rollers for 10 minutes.\", \"Wavy hair: leave slightly extra length so the wave sits naturally, and check the shape once dry.\", \"Thick hair: remove bulk at the crown and sides with texturising or thinning shears.\", \"Follow the customer\'s oval face shape and head shape; check symmetry in the mirror before finishing.\"]}','/api/v1/instructions/14/audio?selection_id=63'),(56,64,'{\"steps\": [\"1. Cut short choppy layers at the crown with a razor.\", \"2. Keep length at the back and sides, thinned out.\", \"3. Add a curtain fringe.\", \"4. Scrunch-dry with texture spray.\", \"Curly hair shrinks when dry: cut dry or leave about 1 cm extra length on top and the fringe.\", \"Thick hair: remove bulk at the crown and sides with texturising or thinning shears.\", \"Follow the customer\'s oval face shape and head shape; check symmetry in the mirror before finishing.\"]}','/api/v1/instructions/33/audio?selection_id=64'),(57,65,'{\"steps\": [\"1. #2 guard on sides tapering to #1 at the nape.\", \"2. Top cut to 1.5-2 inches, graduated longer to the front.\", \"3. Hard-define the side part with a comb.\", \"4. Style with a low-shine pomade.\"]}','/api/v1/instructions/24/audio?selection_id=65'),(58,66,'{\"steps\": [\"1. #2 guard on sides tapering to #1 at the nape.\", \"2. Top cut to 1.5-2 inches, graduated longer to the front.\", \"3. Hard-define the side part with a comb.\", \"4. Style with a low-shine pomade.\"]}','/api/v1/instructions/24/audio?selection_id=66'),(59,67,'{\"steps\": [\"1. Apply volumizing mousse to damp roots.\", \"2. Blow-dry section by section with 2-inch ceramic round brush.\", \"3. Set front sections in Velcro rollers for 10 minutes.\"]}','/api/v1/instructions/14/audio?selection_id=67'),(60,68,'{\"steps\": [\"1. Low taper from #1 at the neckline to #2 on the sides.\", \"2. Leave 2 inches on top.\", \"3. Blow-dry the top over to one side.\", \"4. Finish with medium-hold pomade.\", \"Thick hair: remove bulk at the crown and sides with texturising or thinning shears.\", \"The customer wears a fringe now: confirm the new fringe length with them before cutting the front.\", \"Follow the customer\'s oval face shape and head shape; check symmetry in the mirror before finishing.\"]}','/api/v1/instructions/25/audio?selection_id=68'),(61,69,'{\"steps\": [\"1. Establish U-shaped perimeter baseline at mid-back.\", \"2. Slide-cut front layers starting from chin down to ends.\", \"3. Blow-dry inward with large round brush.\", \"Wavy hair: leave slightly extra length so the wave sits naturally, and check the shape once dry.\", \"Thick hair: remove bulk at the crown and sides with texturising or thinning shears.\"]}','/api/v1/instructions/10/audio?selection_id=69'),(62,70,'{\"steps\": [\"1. Curve drop fade around ear to nape.\", \"2. Point-cut forward fringe for messy texture.\", \"Curly hair shrinks when dry: cut dry or leave about 1 cm extra length on top and the fringe.\", \"Thick hair: remove bulk at the crown and sides with texturising or thinning shears.\"]}','/api/v1/instructions/17/audio?selection_id=70');
