CREATE TABLE `hairstyles` (
  `id` int NOT NULL AUTO_INCREMENT,
  `style_code` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `category` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `suitable_face_shapes` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `suitable_hair_types` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `suitable_hair_lengths` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `suitable_hair_densities` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `gender` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `maintenance_level` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `requires_chemical_service` tinyint(1) NOT NULL,
  `chemical_service_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `chemical_formula_instructions` text COLLATE utf8mb4_unicode_ci,
  `description` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `stylist_instructions` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `preview_image_url` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL,
  `side_image_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `back_image_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `ix_hairstyles_style_code` (`style_code`),
  KEY `ix_hairstyles_id` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=306 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
