INSERT INTO `hairstyles` VALUES (1,'HAIR_M_001','Low Taper Fade + Textured Top','Trendy','Oval,Square,Round,Diamond','1A,1B,1C,2A,2B','Short','Fine,Medium,Thick','Male','Medium',0,NULL,NULL,'Clean skin taper fade on the sides with textured length on top for modern movement.','1. Use #1 guard to start low taper at sideburns and nape.\n2. Blend into #2 guard moving upward.\n3. Point-cut 2 inches on top for textured volume.\n4. Apply matte clay for natural finish.','https://images.unsplash.com/photo-1622286342621-4bd786c2447c?w=600&auto=format&fit=crop','https://images.unsplash.com/photo-1503951914875-452162b0f3f1?w=600&auto=format&fit=crop','https://images.unsplash.com/photo-1519085360753-af0119f7cbe7?w=600&auto=format&fit=crop'),(2,'HAIR_M_002','Classic Executive Side Part','Classic','Oval,Round,Heart','1A,1B,1C','Medium','Fine,Medium','Male','Low',0,NULL,NULL,'Timeless professional side part combed clean with subtle taper on the neckline.','1. Establish clean side parting along natural hair swirl.\n2. Scissors over comb for sides down to #3 guard.\n3. Layer top to 3 inches tapering back smoothly.\n4. Style with water-based pomade.','https://images.unsplash.com/photo-1503951914875-452162b0f3f1?w=600&auto=format&fit=crop','https://images.unsplash.com/photo-1622286342621-4bd786c2447c?w=600&auto=format&fit=crop','https://images.unsplash.com/photo-1500648767791-00dcc994a43e?w=600&auto=format&fit=crop'),(3,'HAIR_M_003','Mid Skin Fade + Textured Quiff','Trendy','Oval,Square,Diamond','1B,1C,2A,2B','Short','Medium,Thick','Male','High',0,NULL,NULL,'Dynamic elevated quiff with sharp mid-height skin fade and seamless top transition.','1. Mid skin fade starting at temples.\n2. Blow dry top upward with round brush.\n3. Finish with high-hold texture powder.','https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?w=600&auto=format&fit=crop',NULL,NULL),(4,'HAIR_M_004','Modern Buzz Cut + Precision Line Up','Professional','Oval,Square','1A,1B,2A,3A,4A','Short','Fine,Medium,Thick','Male','Low',0,NULL,NULL,'Ultra-clean uniform buzz cut with razor-sharp hairline edging for low maintenance elegance.','1. Clipper cut #2 guard overall.\n2. Detail hairline with open razor line-up.','https://images.unsplash.com/photo-1506794778202-cad84cf45f1d?w=600&auto=format&fit=crop',NULL,NULL),(5,'HAIR_F_001','Curtain Bangs + Soft Layered Waves','Trendy','Oval,Round,Heart,Square','1B,1C,2A,2B,2C','Long','Medium,Thick','Female','Medium',0,NULL,NULL,'Face-framing curtain bangs parted in the center flowing into soft cascading layers.','1. Section center parting and cut curtain bangs sweeping past cheekbones at 45-degree angle.\n2. Create 90-degree interior long layers from collarbone down.\n3. Point-cut ends for soft seamless weight distribution.\n4. Blow-dry with large barrel round brush curling outward.\n5. Finish with light shine serum.','https://images.unsplash.com/photo-1534528741775-53994a69daeb?w=600&auto=format&fit=crop','https://images.unsplash.com/photo-1580618672591-eb180b1a973f?w=600&auto=format&fit=crop','https://images.unsplash.com/photo-1517841905240-472988babdf9?w=600&auto=format&fit=crop'),(6,'HAIR_F_002','Classic Chic French Bob','Classic','Oval,Heart,Diamond','1A,1B,1C,2A','Bob','Fine,Medium','Female','Low',0,NULL,NULL,'Elegant chin-length bob with subtle internal layering for natural movement and volume.','1. Establish perimeter baseline cut parallel to jawline.\n2. Elevate crown sections 90 degrees for soft top volume.\n3. Texturize weight behind ears with thinning shears.\n4. Smooth blow-dry with flat iron bevel at ends.','https://images.unsplash.com/photo-1580618672591-eb180b1a973f?w=600&auto=format&fit=crop','https://images.unsplash.com/photo-1534528741775-53994a69daeb?w=600&auto=format&fit=crop','https://images.unsplash.com/photo-1560869713-7d0a29430803?w=600&auto=format&fit=crop'),(7,'HAIR_F_003','Honey Balayage + Beach Curls','Trendy','Oval,Round,Square','2B,2C,3A,3B','Long','Medium,Thick','Female','High',1,'Balayage Lightening & Glossing','1. Lightener: 20 Vol Developer (1:1.5 ratio) applied hand-painted V-sections.\n2. Processing time: 35 minutes room temp.\n3. Gloss Toner: 9G + 9N Demi-permanent gloss for 10 minutes at basin.','Hand-painted honey gold balayage highlights blending into voluminous 3A/3B curls.','1. Apply hand-painted V-section balayage highlights starting 3 inches from roots.\n2. Cut long 180-degree interior layers to encourage natural curl bounce.\n3. Diffuse-dry with curl cream and finishing argan oil.','https://images.unsplash.com/photo-1560869713-7d0a29430803?w=600&auto=format&fit=crop','https://images.unsplash.com/photo-1534528741775-53994a69daeb?w=600&auto=format&fit=crop','https://images.unsplash.com/photo-1517841905240-472988babdf9?w=600&auto=format&fit=crop'),(8,'HAIR_F_004','Sleek Executive Straight Lob','Professional','Round,Oval,Square','1A,1B,1C','Lob','Medium,Thick','Female','Low',0,NULL,NULL,'Polished shoulder-grazing long bob with blunt edges for a commanding professional look.','1. Cut sharp zero-degree blunt line at collarbone.\n2. Slight bevel layering on front 2 inches.\n3. Apply thermal protector and flat-iron pin straight.\n4. Finish with anti-humidity spray.','https://images.unsplash.com/photo-1517841905240-472988babdf9?w=600&auto=format&fit=crop','https://images.unsplash.com/photo-1580618672591-eb180b1a973f?w=600&auto=format&fit=crop','https://images.unsplash.com/photo-1534528741775-53994a69daeb?w=600&auto=format&fit=crop'),(9,'HAIR_U_001','Coily Afro Crown + Tapered Sides','Trendy','Oval,Square,Diamond','4A,4B,4C','Medium','Medium,Thick','Unisex','Medium',0,NULL,NULL,'Sculpted 4A-4C coily afro crown with crisp low tapered hairline framing the temple.','1. Freehand pick and shape the 4C coily crown to spherical balance.\n2. Low clipper taper on sideburns and nape (#1 to #2 guard).\n3. Apply leave-in curl conditioner and twist sponge for coil definition.','https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?w=600&auto=format&fit=crop','https://images.unsplash.com/photo-1500648767791-00dcc994a43e?w=600&auto=format&fit=crop','https://images.unsplash.com/photo-1560869713-7d0a29430803?w=600&auto=format&fit=crop'),(10,'HAIR_F_005','Layered Feathered U-Cut','Classic','Oval,Round,Heart','1A,1B,1C,2A','Long','Medium,Thick','Female','Low',0,NULL,NULL,'Flowing U-shaped back profile with feathered face-framing layers for dense long hair.','1. Establish U-shaped perimeter baseline at mid-back.\n2. Slide-cut front layers starting from chin down to ends.\n3. Blow-dry inward with large round brush.','https://images.unsplash.com/photo-1534528741775-53994a69daeb?w=600&auto=format&fit=crop',NULL,NULL),(11,'HAIR_F_006','Face-Framing Butterfly Cut','Trendy','Oval,Square,Heart,Diamond','1B,1C,2A,2B','Medium','Fine,Medium,Thick','Female','Medium',0,NULL,NULL,'Voluminous two-tier butterfly layers creating the illusion of a short bob in front and long hair in back.','1. Cut shorter top layer framing cheekbones.\n2. Connect to longer bottom interior layer with point-cutting.\n3. Style with root volume spray.','https://images.unsplash.com/photo-1580618672591-eb180b1a973f?w=600&auto=format&fit=crop',NULL,NULL),(12,'HAIR_F_007','Textured Pixie Cut + Side Bangs','Trendy','Oval,Heart,Diamond','1A,1B,2A,2B','Short','Fine,Medium','Female','Low',0,NULL,NULL,'Chic low-maintenance textured pixie cut with soft side-swept bangs framing eyebrows.','1. Taper nape and sides cleanly with shears.\n2. Razor-cut top layers for piecey texture.\n3. Style with lightweight texturizing paste.','https://images.unsplash.com/photo-1517841905240-472988babdf9?w=600&auto=format&fit=crop',NULL,NULL),(13,'HAIR_F_008','South Asian Traditional Braided Crown','Classic','Oval,Round,Square,Heart','1C,2A,2B,2C,3A','Long','Medium,Thick','Female','Medium',0,NULL,NULL,'Elegant low traditional braid with subtle crown volume and decorative hair accessories compatibility.','1. Tease crown gently for subtle height.\n2. Create neat three-strand braid extending down back.\n3. Secure end with silk band and smooth flyaways with serum.','https://images.unsplash.com/photo-1560869713-7d0a29430803?w=600&auto=format&fit=crop',NULL,NULL),(14,'HAIR_F_009','Glamorous Volume Blowout + Soft Layers','Professional','Oval,Round,Heart,Square','1A,1B,1C,2A','Long','Medium,Thick','Female','Low',0,NULL,NULL,'High-shine red carpet blowout with bouncy outward-turned curtain layers.','1. Apply volumizing mousse to damp roots.\n2. Blow-dry section by section with 2-inch ceramic round brush.\n3. Set front sections in Velcro rollers for 10 minutes.','https://images.unsplash.com/photo-1534528741775-53994a69daeb?w=600&auto=format&fit=crop',NULL,NULL),(15,'HAIR_F_010','Silk Keratin Smoothening + Glass Shine','Professional','Oval,Round,Square','2A,2B,2C,3A,3B','Medium','Medium,Thick','Female','High',1,'Keratin Protein Infusion Treatment','1. Clarifying Shampoo wash twice.\n2. Apply Formaldehyde-free Keratin treatment 0.5 inches from scalp.\n3. Blow-dry 100% and flat iron at 230°C in thin micro-sections.','Frizz-free ultra-sleek mirror shine treatment transforming wavy/frizzy hair into silky straight locks.','1. Apply Keratin treatment evenly.\n2. Flat-iron micro sections 7-10 times at 230°C to lock in protein.','https://images.unsplash.com/photo-1580618672591-eb180b1a973f?w=600&auto=format&fit=crop',NULL,NULL),(16,'HAIR_M_005','Slicked Back Undercut','Classic','Oval,Square','1A,1B,1C,2A','Medium','Medium,Thick','Male','Medium',0,NULL,NULL,'Sharp undercut sides with high-shine slicked back crown for executive flair.','1. Disconnected undercut on sides at #1.5 guard.\n2. Comb 4 inches on top straight back with gloss pomade.','https://images.unsplash.com/photo-1622286342621-4bd786c2447c?w=600&auto=format&fit=crop',NULL,NULL),(17,'HAIR_M_006','Messy Textured Fringe + Drop Fade','Trendy','Heart,Oval,Round','2A,2B,2C,3A','Short','Fine,Medium,Thick','Male','Medium',0,NULL,NULL,'Forward-falling textured crop fringe paired with a curving drop fade along the nape.','1. Curve drop fade around ear to nape.\n2. Point-cut forward fringe for messy texture.','https://images.unsplash.com/photo-1503951914875-452162b0f3f1?w=600&auto=format&fit=crop',NULL,NULL),(18,'HAIR_M_007','Executive Pompadour Fade','Professional','Oval,Round,Square','1B,1C,2A','Medium','Medium,Thick','Male','High',0,NULL,NULL,'Voluminous pompadour front swept high with tapered side burn transition.','1. Blow dry front pomp 3 inches high.\n2. Taper sides cleanly.','https://images.unsplash.com/photo-1500648767791-00dcc994a43e?w=600&auto=format&fit=crop',NULL,NULL),(19,'HAIR_M_008','Natural Curly High Top Fade','Trendy','Oval,Square,Diamond','3A,3B,3C,4A','Medium','Medium,Thick','Male','Medium',0,NULL,NULL,'Defined natural curl height on top balanced with crisp temple skin fade.','1. High skin fade.\n2. Shape curls on top with curl sponge and leave-in cream.','https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?w=600&auto=format&fit=crop',NULL,NULL),(20,'HAIR_U_002','Textured Shag Cut + Wispy Fringe','Trendy','Oval,Heart,Diamond','1C,2A,2B,2C','Medium','Fine,Medium,Thick','Unisex','Low',0,NULL,NULL,'Modern rock-and-roll shag with heavily razored crown layers and effortless curtain fringe.','1. Razor-cut choppy interior crown layers.\n2. Connect to light curtain fringe.\n3. Scrunch dry with sea salt spray.','https://images.unsplash.com/photo-1517841905240-472988babdf9?w=600&auto=format&fit=crop',NULL,NULL),(21,'HAIR_M_009','Classic Crew Cut','Classic','Oval,Square,Rectangle,Round','1A,1B,1C,2A,2B','Short','Fine,Medium,Thick','Male','Low',0,NULL,NULL,'Timeless short crew cut: tapered sides with slightly longer top brushed forward or up.','1. #2 guard on sides and back, tapering to #1 at the neckline.\n2. Scissor-cut top to 1-1.5 inches, slightly longer at the front.\n3. Blend the top into the sides with scissor-over-comb.\n4. Light matte paste brushed up at the front.','',NULL,NULL),(22,'HAIR_M_010','Ivy League Cut','Classic','Oval,Square,Heart,Rectangle','1A,1B,1C,2A','Short','Medium,Thick','Male','Medium',0,NULL,NULL,'Neat Ivy League (Harvard) cut: short tapered sides with enough length on top for a clean side part.','1. #2 to #3 taper on sides and back.\n2. Leave 1.5-2 inches on top, longest at the front.\n3. Define a side part on the natural parting.\n4. Comb to the side with light pomade.','',NULL,NULL),(23,'HAIR_M_011','Short Back & Sides','Classic','Oval,Round,Square,Diamond','1A,1B,1C,2A,2B','Short','Fine,Medium,Thick','Male','Low',0,NULL,NULL,'Traditional gentleman\'s short back and sides with a tidy, natural top.','1. Scissor-over-comb or #3 guard on back and sides.\n2. Square the neckline and tidy around the ears.\n3. Cut the top to 1.5-2 inches following head shape.\n4. Finish with a light cream, natural fall.','',NULL,NULL),(24,'HAIR_M_012','Short Business Side Part','Professional','Oval,Round,Heart,Rectangle','1A,1B,1C,2A','Short','Fine,Medium,Thick','Male','Low',0,NULL,NULL,'Clean, office-ready short side part with a soft taper and neat finish.','1. #2 guard on sides tapering to #1 at the nape.\n2. Top cut to 1.5-2 inches, graduated longer to the front.\n3. Hard-define the side part with a comb.\n4. Style with a low-shine pomade.','',NULL,NULL),(25,'HAIR_M_013','Clean Comb-Over Taper','Professional','Oval,Square,Round','1A,1B,1C,2A','Short','Medium,Thick','Male','Medium',0,NULL,NULL,'Polished comb-over with a tight taper for a sharp professional look.','1. Low taper from #1 at the neckline to #2 on the sides.\n2. Leave 2 inches on top.\n3. Blow-dry the top over to one side.\n4. Finish with medium-hold pomade.','',NULL,NULL),(26,'HAIR_M_014','Caesar Cut','Professional','Oval,Rectangle,Heart','1A,1B,2A,2B,3A','Short','Fine,Medium,Thick','Male','Low',0,NULL,NULL,'Low-maintenance Caesar cut: short even length with a straight, short fringe.','1. #3 guard on sides and back.\n2. Cut top to about 1 inch, brushed forward.\n3. Cut a straight, blunt short fringe across the forehead.\n4. Texture the top lightly with point-cutting.','',NULL,NULL),(27,'HAIR_M_015','Textured French Crop','Trendy','Oval,Square,Round,Rectangle','1A,1B,1C,2A,2B','Short','Medium,Thick','Male','Low',0,NULL,NULL,'Modern French crop: faded sides with a choppy textured top and a short blunt fringe.','1. Low or mid fade on the sides.\n2. Leave 1.5 inches on top, point-cut for texture.\n3. Cut a short, blunt fringe.\n4. Finish with matte texture powder.','',NULL,NULL),(28,'HAIR_W_011','Long Layers + Side-Swept Fringe','Classic','Oval,Round,Square,Rectangle','1A,1B,1C,2A,2B','Long','Fine,Medium,Thick','Female','Low',0,NULL,NULL,'Graceful long layers with a soft side-swept fringe that flatters most faces.','1. Keep the perimeter length, cut layers at 90 degrees from the chin down.\n2. Cut a long side-swept fringe from a deep side part.\n3. Soften ends with point-cutting.\n4. Blow-dry with a round brush, fringe swept to the side.','',NULL,NULL),(29,'HAIR_W_012','Classic Layered Lob','Classic','Oval,Round,Heart,Square','1A,1B,1C,2A,2B','Lob','Fine,Medium,Thick','Female','Low',0,NULL,NULL,'Shoulder-length long bob with soft layers for movement and easy styling.','1. Cut the perimeter just above the shoulders.\n2. Add long internal layers at 45 degrees.\n3. Soften the front with face-framing pieces.\n4. Blow-dry smooth with a slight bend at the ends.','',NULL,NULL),(30,'HAIR_W_013','Polished Blunt Bob','Professional','Oval,Heart,Rectangle','1A,1B,1C,2A','Bob','Medium,Thick','Female','Low',0,NULL,NULL,'Sharp, polished chin-length blunt bob for a confident professional look.','1. Cut a 0-degree blunt perimeter at chin level.\n2. Keep the interior unlayered for a solid line.\n3. Side or centre parting as preferred.\n4. Flat-iron smooth for a glossy finish.','',NULL,NULL),(31,'HAIR_W_014','Sleek Step Cut','Professional','Oval,Round,Rectangle','1A,1B,1C,2A','Long','Medium,Thick','Female','Low',0,NULL,NULL,'Long step cut with clean, visible tiers that keeps length while adding shape.','1. Keep the perimeter length.\n2. Cut 3-4 distinct steps at the front and sides, starting at the chin.\n3. Keep each step blunt for definition.\n4. Blow-dry straight and sleek.','',NULL,NULL),(32,'HAIR_W_015','Korean C-Curl Layers','Trendy','Oval,Round,Heart,Square','1A,1B,1C,2A','Medium','Fine,Medium,Thick','Female','Medium',0,NULL,NULL,'Soft Korean-style layers with ends curled inward in a gentle C shape.','1. Cut medium layers from the collarbone.\n2. Add soft see-through face-framing pieces.\n3. Blow-dry ends under with a round brush or C-curl iron.\n4. Light hair oil for shine.','',NULL,NULL),(33,'HAIR_W_016','Soft Wolf Cut','Trendy','Oval,Heart,Diamond,Rectangle','1C,2A,2B,2C','Medium','Medium,Thick','Female','Medium',0,NULL,NULL,'Trendy wolf cut: choppy volume at the crown blending into wispy, longer ends.','1. Cut short choppy layers at the crown with a razor.\n2. Keep length at the back and sides, thinned out.\n3. Add a curtain fringe.\n4. Scrunch-dry with texture spray.','',NULL,NULL),(101,'BEARD_001','Sharp Boxed Beard','Professional','Oval,Round','','','','Male','',0,NULL,NULL,'Crisp geometric beard shape with defined cheek lines and square chin.','1. Trim overall length to 8mm.\n2. Edge cheek lines sharp at 45 degrees.\n3. Clean neck line 1 inch above adams apple.','https://images.unsplash.com/photo-1622286342621-4bd786c2447c?w=600&auto=format&fit=crop',NULL,NULL),(102,'BEARD_002','Designer Heavy Stubble','Trendy','Oval,Square,Heart,Diamond','','','','Male','',0,NULL,NULL,'Rugged 3-day stubble look with soft blended edges.','1. Use 3mm guard over entire beard area.\n2. Taper neck fade smoothly.','https://images.unsplash.com/photo-1506794778202-cad84cf45f1d?w=600&auto=format&fit=crop',NULL,NULL),(103,'BEARD_003','Short Corporate Beard','Professional','Oval,Round,Square,Rectangle','','','','Male','',0,NULL,NULL,'Neat, even short beard about 5 mm with clean cheek and neck lines for the office.','1. Trim the whole beard evenly with a 5 mm guard.\n2. Define a natural, low cheek line.\n3. Clean the neckline one finger above the Adam\'s apple.\n4. Tidy the moustache above the lip line.','',NULL,NULL),(104,'BEARD_004','Classic Full Beard','Classic','Oval,Rectangle,Diamond,Heart','','','','Male','',0,NULL,NULL,'Well-groomed full beard about 2 cm, rounded at the chin with a connected moustache.','1. Trim the beard to about 2 cm, slightly longer at the chin.\n2. Round the chin shape.\n3. Shape the cheek line and neckline.\n4. Trim the moustache off the lip; finish with beard oil.','',NULL,NULL),(105,'BEARD_005','Clean Shave','Classic','Oval,Round,Square,Heart,Diamond,Rectangle','','','','Male','',0,NULL,NULL,'Smooth, traditional clean shave for a fresh, polished look.','1. Trim existing beard short with clippers.\n2. Hot towel and pre-shave oil.\n3. Shave with the grain, then a careful second pass.\n4. Cold towel and alcohol-free aftershave balm.','',NULL,NULL),(106,'BEARD_006','Van Dyke Goatee','Trendy','Round,Oval,Square','','','','Male','',0,NULL,NULL,'Stylish Van Dyke: chin beard and separate moustache with clean-shaven cheeks.','1. Shave the cheeks and sides of the jaw clean.\n2. Shape a chin beard about 1 cm, slightly pointed.\n3. Shape a separate moustache, leaving a small gap at the mouth corners.\n4. Define lines with a trimmer.','',NULL,NULL),(107,'BEARD_007','Faded Short Beard','Trendy','Oval,Square,Round,Diamond','','','','Male','',0,NULL,NULL,'Modern short beard that fades from the sideburns into a fuller chin.','1. Fade the sideburns from 1 mm up to 6 mm.\n2. Keep the jaw and chin at 8 mm.\n3. Sharp cheek line, clean neckline.\n4. Blend with a trimmer for a smooth gradient.','',NULL,NULL),(108,'BEARD_008','Circle Beard','Classic','Square,Oval,Rectangle','','','','Male','',0,NULL,NULL,'Traditional circle beard: moustache joined to a rounded chin beard, cheeks clean.','1. Shave the cheeks clean.\n2. Keep moustache and chin beard at about 6 mm.\n3. Connect them in a rounded circle around the mouth.\n4. Define the outline with a trimmer.','',NULL,NULL),(109,'BEARD_009','Light Stubble','Professional','Oval,Round,Square,Heart,Diamond,Rectangle','','','','Male','',0,NULL,NULL,'Subtle, even 1-2 mm stubble with a tidy neckline for a smart, low-effort look.','1. Trim the whole beard area with a 1.5 mm guard.\n2. Clean the neckline and cheek edges.\n3. Keep the moustache the same length.','',NULL,NULL),(110,'BEARD_010','Chevron Moustache + Stubble','Classic','Oval,Rectangle,Square','','','','Male','',0,NULL,NULL,'Bold, full chevron moustache over light stubble.','1. Trim the beard area to 2 mm stubble.\n2. Keep the moustache full, trimmed to the top of the lip.\n3. Shape the moustache into a slight downward chevron.\n4. Comb and finish with moustache wax.','',NULL,NULL),(201,'COLOUR_001','Rich Chocolate Brown Global Colour','Classic','Oval,Round,Square,Heart,Diamond,Rectangle','1A,1B,1C,2A,2B,2C,3A,3B,3C,4A,4B,4C','Any','Fine,Medium,Thick','Unisex','Medium',1,'Rich Chocolate Brown Global Colour',NULL,'All-over rich chocolate brown colour with natural shine; keeps your current cut.','1. Strand test and skin patch test 48 hours before.\n2. Apply level 4 chocolate brown from roots to ends.\n3. Process 30-35 minutes.\n4. Rinse, colour-lock conditioner, gloss finish.','',NULL,NULL),(202,'COLOUR_002','Natural Black Grey Coverage','Professional','Oval,Round,Square,Heart,Diamond,Rectangle','1A,1B,1C,2A,2B,2C,3A,3B,3C,4A,4B,4C','Any','Fine,Medium,Thick','Unisex','Medium',1,'Natural Black Grey Coverage',NULL,'Natural soft-black colour that covers grey hair evenly for a clean, professional look.','1. Patch test 48 hours before.\n2. Apply soft black (level 2-3) to roots first, then lengths.\n3. Process 30 minutes for full grey coverage.\n4. Rinse and condition.','',NULL,NULL),(203,'COLOUR_003','Caramel Highlights','Trendy','Oval,Round,Square,Heart,Diamond,Rectangle','1A,1B,1C,2A,2B,2C,3A,3B,3C,4A,4B,4C','Any','Fine,Medium,Thick','Female','Medium',1,'Caramel Highlights',NULL,'Fine caramel highlights woven through the hair for brightness and dimension.','1. Weave fine sections through the top and sides.\n2. Lighten to level 7 caramel.\n3. Tone to a warm caramel.\n4. Rinse, bond treatment, blow-dry.','',NULL,NULL),(204,'COLOUR_004','Burgundy Wine Colour','Trendy','Oval,Round,Square,Heart,Diamond,Rectangle','1A,1B,1C,2A,2B,2C,3A,3B,3C,4A,4B,4C','Any','Fine,Medium,Thick','Female','Medium',1,'Burgundy Wine Colour',NULL,'Deep burgundy wine colour with a rich red-violet shine.','1. Patch test 48 hours before.\n2. Apply a burgundy red-violet shade from roots to ends.\n3. Process 35 minutes.\n4. Rinse with cool water; colour-protect conditioner.','',NULL,NULL),(205,'COLOUR_005','Soft Ash Brown Balayage','Classic','Oval,Round,Square,Heart,Diamond,Rectangle','1A,1B,1C,2A,2B,2C,3A,3B,3C,4A,4B,4C','Any','Fine,Medium,Thick','Female','Medium',1,'Soft Ash Brown Balayage',NULL,'Soft hand-painted ash-brown balayage that grows out naturally.','1. Hand-paint ash-brown lightener from mid-lengths to ends.\n2. Keep roots natural.\n3. Tone to a cool ash brown.\n4. Rinse, gloss and blow-dry.','',NULL,NULL),(206,'COLOUR_006','Men\'s Grey Blending','Professional','Oval,Round,Square,Heart,Diamond,Rectangle','1A,1B,1C,2A,2B,2C,3A,3B,3C,4A,4B,4C','Any','Fine,Medium,Thick','Male','Medium',1,'Men\'s Grey Blending',NULL,'Subtle grey blending that softens grey hair without a solid dyed look.','1. Choose a shade one level lighter than the natural base.\n2. Apply quickly to the whole head.\n3. Process 5-10 minutes only.\n4. Rinse; grey is softened, not fully covered.','',NULL,NULL),(207,'COLOUR_007','Men\'s Natural Dark Brown','Classic','Oval,Round,Square,Heart,Diamond,Rectangle','1A,1B,1C,2A,2B,2C,3A,3B,3C,4A,4B,4C','Any','Fine,Medium,Thick','Male','Medium',1,'Men\'s Natural Dark Brown',NULL,'Even natural dark brown colour for a fresh, healthy look.','1. Patch test 48 hours before.\n2. Apply level 3-4 natural dark brown.\n3. Process 20-25 minutes.\n4. Rinse and condition.','',NULL,NULL),(208,'COLOUR_008','Men\'s Ash Highlights','Trendy','Oval,Round,Square,Heart,Diamond,Rectangle','1A,1B,1C,2A,2B,2C,3A,3B,3C,4A,4B,4C','Any','Fine,Medium,Thick','Male','Medium',1,'Men\'s Ash Highlights',NULL,'Textured ash-blonde highlights on the top for a modern look.','1. Foil fine sections on the top only.\n2. Lighten to level 8.\n3. Tone to a cool ash.\n4. Rinse and style with matte paste.','',NULL,NULL),(209,'COLOUR_009','Copper Glow Highlights','Trendy','Oval,Round,Square,Heart,Diamond,Rectangle','1A,1B,1C,2A,2B,2C,3A,3B,3C,4A,4B,4C','Any','Fine,Medium,Thick','Female','Medium',1,'Copper Glow Highlights',NULL,'Warm copper highlights that add glow around the face.','1. Face-framing and crown sections in foils.\n2. Lighten and tone to warm copper.\n3. Process 30 minutes.\n4. Rinse, gloss and blow-dry.','',NULL,NULL),(301,'TEXTURE_001','Men\'s Keratin Smoothening','Professional','Oval,Round,Square,Heart,Diamond,Rectangle','1A,1B,1C,2A,2B,2C,3A,3B,3C,4A,4B,4C','Any','Fine,Medium,Thick','Male','Medium',1,'Chemical Texture Treatment',NULL,'Frizz-free, smooth and manageable hair that keeps your current cut.','1. Clarifying wash.\n2. Apply keratin evenly, avoiding the scalp.\n3. Blow-dry and flat-iron at 200-210 C.\n4. No washing for 48 hours.','',NULL,NULL),(302,'TEXTURE_002','Hair Botox Frizz Control','Classic','Oval,Round,Square,Heart,Diamond,Rectangle','1A,1B,1C,2A,2B,2C,3A,3B,3C,4A,4B,4C','Any','Fine,Medium,Thick','Unisex','Medium',1,'Chemical Texture Treatment',NULL,'Deep conditioning treatment that softens frizz and adds shine while keeping natural movement.','1. Clarifying wash.\n2. Apply botox treatment section by section.\n3. Leave 30 minutes, rinse partially.\n4. Blow-dry and light flat-iron.','',NULL,NULL),(303,'TEXTURE_003','Soft Beach-Wave Perm','Trendy','Oval,Round,Square,Heart,Diamond,Rectangle','1A,1B,1C,2A,2B,2C,3A,3B,3C,4A,4B,4C','Any','Fine,Medium,Thick','Female','Medium',1,'Chemical Texture Treatment',NULL,'Loose, natural-looking beach waves that last for months.','1. Wrap on large perm rods in a brick pattern.\n2. Apply waving lotion, process per hair condition.\n3. Neutralise and rinse.\n4. Diffuse-dry with curl cream.','',NULL,NULL),(304,'TEXTURE_004','Japanese Straightening','Classic','Oval,Round,Square,Heart,Diamond,Rectangle','1A,1B,1C,2A,2B,2C,3A,3B,3C,4A,4B,4C','Any','Fine,Medium,Thick','Female','Medium',1,'Chemical Texture Treatment',NULL,'Permanent, poker-straight smooth hair with a glossy finish.','1. Apply straightening cream section by section.\n2. Process, rinse and blow-dry.\n3. Flat-iron in very fine sections.\n4. Apply neutraliser and rinse.','',NULL,NULL),(305,'TEXTURE_005','Men\'s Texture Perm','Trendy','Oval,Round,Square,Heart,Diamond,Rectangle','1A,1B,1C,2A,2B,2C,3A,3B,3C,4A,4B,4C','Any','Fine,Medium,Thick','Male','Medium',1,'Chemical Texture Treatment',NULL,'Loose curls on top for natural volume and movement.','1. Wrap the top section on medium perm rods.\n2. Process with a gentle waving lotion.\n3. Neutralise and rinse.\n4. Style with curl cream; sides unchanged.','',NULL,NULL);
