INSERT INTO `instruction_translations` VALUES (1,10,'hi','e3939c3b7e3dcedeb040db8466046006b7be09bc277115a8e68b3db54c0258a6','{\"steps\": [\"पीठ के बीच तक U-आकार की आउटलाइन बनाएं।\", \"आगे के लेयर्स को ठोड़ी से शुरू करके नीचे तक काटें।\", \"बड़े राउंड ब्रश से बालों को अंदर की ओर ब्लो-ड्राई करें।\", \"घुंघराले बाल: थोड़ी ज़्यादा लंबाई छोड़ें ताकि वे अपने आप बैठ जाएं, और सूखने के बाद शेप चेक करें।\"]}','2026-10-07 07:10:12'),(2,10,'hi','e3939c3b7e3dcedeb040db8466046006b7be09bc277115a8e68b3db54c0258a6','{\"steps\": [\"पीछे के आधे हिस्से पर U-आकार में कटाई की शुरुआत करें।\", \"ठोड़ी से शुरू करते हुए, आगे के बालों को किनारों तक स्लाइड-कट से काटें।\", \"बड़े गोल ब्रश से बालों को अंदर की ओर ब्लो-ड्राई करें।\", \"घुंघराले बालों के लिए: थोड़ी ज़्यादा लंबाई छोड़ दें ताकि लहरें नैचुरली बैठें, और सूखने के बाद शेप चेक करें।\"]}','2026-10-07 07:10:12'),(3,10,'ta','e3939c3b7e3dcedeb040db8466046006b7be09bc277115a8e68b3db54c0258a6','{\"steps\": [\"முதுகுக்கு நடுவில் U-வடிவில் ஒரு அடிப்படை கோடு போடுங்கள்.\", \"கன்னத்திலிருந்து முனைகள் வரை முன்பக்க அடுக்குகளை ஸ்லைடு-கட் செய்யுங்கள்.\", \"பெரிய ரவுண்ட் பிரஷ்ஷை பயன்படுத்தி உள்ளே பார்த்த மாதிரி ப்ளோ-ட்ரை செய்யுங்கள்.\", \"அலை அலையான முடியாக இருந்தால், அலைகள் இயற்கையாக இருக்க கொஞ்சம் நீளமாக விடுங்கள், காய்ந்ததும் வடிவத்தை சரிபார்க்கவும்.\"]}','2026-10-07 07:10:57'),(4,10,'ta','e3939c3b7e3dcedeb040db8466046006b7be09bc277115a8e68b3db54c0258a6','{\"steps\": [\"முதுகு நடுப்பகுதி வரை U-வடிவத்தில் ஒரு அடிப்படையை உருவாக்குங்கள்.\", \"கன்னத்தில் இருந்து கீழே முனைகள் வரை முன்பக்க அடுக்குகளை ஸ்லைடு-கட் செய்யுங்கள்.\", \"பெரிய ரவுண்ட் பிரஷ் வைத்து உள்நோக்கி ப்ளோ-ட்ரை செய்யுங்கள்.\", \"அலையான முடி என்றால், அலை இயற்கையாக படிய கொஞ்சம் கூடுதல் நீளம் விடுங்கள், காய்ந்ததும் வடிவத்தை சரிபார்க்கவும்.\"]}','2026-10-07 07:10:59'),(5,3,'ta','778808e5789f462139e23bebf6e1527aa30c74be59a8c6b65e50e7f9ae874968','{\"steps\": [\"காதுக்கு மேலேயிருந்து, தலையின் மேல் வரைக்கும் கொஞ்சம் கொஞ்சமா குறைச்சு வாறுங்க.\", \"மேல இருக்கிற முடியை, சுத்தி சுருட்டும் பிரஷ் வச்சு, மேல நோக்கி ட்ரை பண்ணுங்க.\", \"நல்லா நிக்கும் பவுடர் போட்டு முடிங்க.\", \"வாடிக்கையாளரோட ஓவல் முக வடிவம், தலையோட வடிவம் பாத்து, கண்ணாடி யில் பார்க்குறப்போ சமமா இருக்கா செக் பண்ணிட்டு முடிங்க.\"]}','2026-10-07 07:38:33'),(6,10,'hi','34483f8389786bdb1211683892171ff7f87c0b1d7652cf2c0ac1e4cbe6efc53e','{\"steps\": [\"पीछे के बीच से यू-आकार की आउटलाइन का बेसलाइन बनाओ।\", \"आगे के लेयर्स को ठोड़ी से शुरू करके नीचे तक स्लाइड-कट करो।\", \"बड़ी गोल ब्रश से अंदर की तरफ ब्लो-ड्राई करो।\", \"घुंघराले बाल: थोड़ी ज़्यादा लंबाई छोड़ दो ताकि वेव नैचुरली बैठ जाए, और सूखने के बाद शेप देख लो।\", \"घने बाल: क्राउन और साइड्स से टेक्सचरिंग या थिनिंग कैंची से बाल हटाओ।\"]}','2026-10-13 10:32:07'),(7,17,'hi','154fb33370248670ed379b0c08858e5b682151fd348a6cf2a3fe851a557ea934','{\"steps\": [\"कान के पास से गर्दन तक घुमावदार ड्रॉप फेड।\", \"आगे के फ्रिंज को पॉइंट-कट करें ताकि मैसी टेक्सचर आए।\", \"घुंघराले बाल सूखने पर सिकुड़ते हैं: इन्हें सूखा काटें या ऊपर और फ्रिंज पर करीब 1 सेमी ज़्यादा लंबाई छोड़ें।\", \"घने बाल: क्राउन और साइड्स से टेक्सचराइज़िंग या थिनिंग कैंची से बाल कम करें।\"]}','2026-10-13 12:02:44');
