DROP TABLE IF EXISTS `style_recommendations`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `style_recommendations` (
  `id` int NOT NULL AUTO_INCREMENT,
  `customer_id` int NOT NULL,
  `photo_id` int NOT NULL,
  `target_service_type` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `style_category` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `recommended_style_ids_json` json NOT NULL,
  `created_at` datetime NOT NULL,
  `trim_preference` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
